def get_db_connection():
    conn = sqlite3.connect('final.db')
    conn.row_factory = sqlite3.Row
    return conn
def insert_course_if_not_exists(cursor, name, code, hours, year, semester, major_id):
    existing = cursor.execute(
        """
        SELECT id
        FROM courses
        WHERE major_id = ? AND code = ?
        """,
        (major_id, code)
    ).fetchone()

    if existing:
        return existing['id']

    cursor.execute(
        """
        INSERT INTO courses
        (name, code, hours, year, semester, major_id)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (name, code, hours, year, semester, major_id)
    )

    return cursor.lastrowid
def init_db():
    conn = get_db_connection()
    cursor = conn.cursor()
        # جدول المستخدمين
    # جدول المستخدمين
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            is_admin INTEGER DEFAULT 0
        )
    ''')
    try:
        cursor.execute(
            'ALTER TABLE users ADD COLUMN is_admin INTEGER DEFAULT 0'
        )
    except sqlite3.OperationalError:
        pass
        # جدول موارد المساقات
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS course_resources (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            course_id INTEGER NOT NULL,
            resource_type TEXT NOT NULL,
            title TEXT,
            url TEXT,
            file_path TEXT,
            description TEXT,
            FOREIGN KEY (course_id) REFERENCES courses(id)
        )
    ''')


    cursor.execute('''
        CREATE TABLE IF NOT EXISTS universities (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            logo TEXT
        )
    ''')

    cursor.execute('''
        CREATE TABLE IF NOT EXISTS majors (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            university_id INTEGER,
            FOREIGN KEY (university_id) REFERENCES universities (id)
        )
    ''')

    cursor.execute('''
        CREATE TABLE IF NOT EXISTS courses (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            code TEXT,
            hours INTEGER,
            year INTEGER,
            semester INTEGER,
            major_id INTEGER,
            FOREIGN KEY (major_id) REFERENCES majors (id)
        )
    ''')
    # =========================================================
    # منع إعادة بناء البيانات عند كل تشغيل
    # =========================================================

    universities_count = cursor.execute(
        'SELECT COUNT(*) FROM universities'
    ).fetchone()[0]

    majors_count = cursor.execute(
        'SELECT COUNT(*) FROM majors'
    ).fetchone()[0]

    courses_count = cursor.execute(
        'SELECT COUNT(*) FROM courses'
    ).fetchone()[0]

    # إذا كانت قاعدة البيانات تحتوي بيانات بالفعل،
    # لا نعيد إدخال البيانات الأساسية مرة أخرى.
    if universities_count > 0 and majors_count > 0 and courses_count > 0:
        conn.commit()
        conn.close()
