@app.route('/university/<int:uni_id>')
@login_required
def show_university(uni_id):

    conn = get_db_connection()

    university = conn.execute(
        'SELECT * FROM universities WHERE id = ?',
        (uni_id,)
    ).fetchone()

    majors = list(conn.execute(
        'SELECT * FROM majors WHERE university_id = ?',
        (uni_id,)
    ).fetchall())

    # تطبيق ترتيب الجامعة إذا كان موجود
    if university['name'] in UNIVERSITY_ORDER:

        order = UNIVERSITY_ORDER[university['name']]

        majors.sort(
            key=lambda x: order.index(x['name'])
            if x['name'] in order
            else 999
        )

    conn.close()

    return render_template(
        'majors.html',
        university=university,
        majors=majors
    )

@app.route('/major/<int:major_id>')
@login_required
def show_major(major_id):
    conn = get_db_connection()
    major = conn.execute('SELECT * FROM majors WHERE id = ?', (major_id,)).fetchone()
    university = conn.execute('SELECT * FROM universities WHERE id = ?', (major['university_id'],)).fetchone()
    # التعديل الجوهري هنا: الترتيب حسب id يضمن نفس تسلسل الإدخال بالضبط
    courses = conn.execute('SELECT * FROM courses WHERE major_id = ? ORDER BY id ASC', (major_id,)).fetchall()
    conn.close()
    return render_template('course_plan.html', major=major, university=university, courses=courses)
@app.route('/course/<int:course_id>')
def course_details(course_id):
    conn = get_db_connection()

    # جلب المساق مع الجامعة التابعة له
    course = conn.execute(
        '''
        SELECT
            courses.*,
            majors.university_id
        FROM courses
        JOIN majors
            ON courses.major_id = majors.id
        WHERE courses.id = ?
        ''',
        (course_id,)
    ).fetchone()

    if course is None:
        conn.close()
        return "المساق غير موجود", 404

    # إذا كان للمساق رمز، نستخدم الرمز كمفتاح للمساق المشترك
    # وإذا لم يكن له رمز، نستخدم اسم المساق
    if course['code']:
        resources = conn.execute(
            '''
            SELECT course_resources.*
            FROM course_resources
            JOIN courses
                ON course_resources.course_id = courses.id
            JOIN majors
                ON courses.major_id = majors.id
            WHERE majors.university_id = ?
              AND courses.code = ?
            ORDER BY course_resources.id ASC
            ''',
            (
                course['university_id'],
                course['code']
            )
        ).fetchall()

    else:
        resources = conn.execute(
            '''
            SELECT course_resources.*
            FROM course_resources
            JOIN courses
                ON course_resources.course_id = courses.id
            JOIN majors
                ON courses.major_id = majors.id
            WHERE majors.university_id = ?
              AND courses.name = ?
            ORDER BY course_resources.id ASC
            ''',
            (
                course['university_id'],
                course['name']
            )
        ).fetchall()

    conn.close()

    return render_template(
        'course_details.html',
        course=course,
        resources=resources
    )

