@app.route('/admin/users/toggle-admin/<int:user_id>', methods=['POST'])
@login_required
def toggle_admin(user_id):
    if session.get('is_admin') != 1:
        return "غير مصرح لك بالدخول إلى لوحة الإدارة", 403

    # منع الأدمن من تغيير صلاحية نفسه
    if user_id == session.get('user_id'):
        return "لا يمكنك تغيير صلاحيتك بنفسك", 400

    conn = get_db_connection()

    user = conn.execute(
        '''
        SELECT id, username, is_admin
        FROM users
        WHERE id = ?
        ''',
        (user_id,)
    ).fetchone()

    if user is None:
        conn.close()
        return "المستخدم غير موجود", 404

    new_status = 0 if user['is_admin'] == 1 else 1

    conn.execute(
        '''
        UPDATE users
        SET is_admin = ?
        WHERE id = ?
        ''',
        (new_status, user_id)
    )

    conn.commit()
    conn.close()

    return redirect(url_for('admin_users'))
@app.route('/admin/resources', methods=['GET', 'POST'])
@login_required
def admin_resources():
    if session.get('is_admin') != 1:
        return "غير مصرح لك بالدخول إلى لوحة الإدارة", 403

    conn = get_db_connection()

    if request.method == 'POST':
        course_id = request.form.get('course_id')
        resource_type = request.form.get('resource_type')
        title = request.form.get('title', '').strip()
        url = request.form.get('url', '').strip()
        description = request.form.get('description', '').strip()

        conn.execute(
            '''
            INSERT INTO course_resources
            (course_id, resource_type, title, url, description)
            VALUES (?, ?, ?, ?, ?)
            ''',
            (
                course_id,
                resource_type,
                title,
                url,
                description
            )
        )

        conn.commit()

    # البحث والفلترة
    search = request.args.get('search', '').strip()
    resource_type_filter = request.args.get('resource_type', '').strip()

    query = '''
        SELECT
            course_resources.*,
            courses.name AS course_name,
            courses.code AS course_code
        FROM course_resources
        JOIN courses
            ON course_resources.course_id = courses.id
        WHERE 1=1
    '''

    params = []

    if search:
        query += '''
            AND (
                course_resources.title LIKE ?
                OR courses.name LIKE ?
                OR courses.code LIKE ?
            )
        '''

        search_value = f'%{search}%'

        params.extend([
            search_value,
            search_value,
            search_value
        ])

    if resource_type_filter:
        query += '''
            AND course_resources.resource_type = ?
        '''

        params.append(resource_type_filter)

    query += '''
        ORDER BY course_resources.id DESC
    '''

    resources = conn.execute(
        query,
        params
    ).fetchall()

    courses = conn.execute(
        '''
        SELECT id, name, code
        FROM courses
        ORDER BY name
        '''
    ).fetchall()

    conn.close()

    return render_template(
        'admin_resources.html',
        courses=courses,
        resources=resources,
        search=search,
        resource_type_filter=resource_type_filter
    )
@app.route('/admin/resources/edit/<int:resource_id>', methods=['GET', 'POST'])
@login_required
def edit_resource(resource_id):
    if session.get('is_admin') != 1:
        return "غير مصرح لك بالدخول إلى لوحة الإدارة", 403

    conn = get_db_connection()

    resource = conn.execute(
        '''
        SELECT *
        FROM course_resources
        WHERE id = ?
        ''',
        (resource_id,)
    ).fetchone()

    if resource is None:
        conn.close()
        return "المورد غير موجود", 404

    if request.method == 'POST':
        course_id = request.form.get('course_id')
        resource_type = request.form.get('resource_type')
        title = request.form.get('title', '').strip()
        url = request.form.get('url', '').strip()
        description = request.form.get('description', '').strip()

        conn.execute(
            '''
            UPDATE course_resources
            SET course_id = ?,
                resource_type = ?,
                title = ?,
                url = ?,
                description = ?
            WHERE id = ?
            ''',
            (
                course_id,
                resource_type,
                title,
                url,
                description,
                resource_id
            )
        )

        conn.commit()
        conn.close()

        return redirect(url_for('admin_resources'))

    courses = conn.execute(
        '''
        SELECT id, name, code
        FROM courses
        ORDER BY name
        '''
    ).fetchall()

    conn.close()

    return render_template(
        'edit_resource.html',
        resource=resource,
        courses=courses
    )
